nextflow_process {
    name "Test Process DATAVZRD"
    script "../main.nf"
    process "DATAVZRD"
    tag "modules"
    tag "modules_nfcore"
    tag "datavzrd"

    test("csv") {

        when {
            process {
                """
                input[0] = [ [id: "csv_config"],
                    file(params.modules_testdata_base_path + 'generic/config/config_test.datavzrd.yaml', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'generic/csv/test.csv', checkIfExists: true)
                    ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                            process.out.findAll { key, val -> key.startsWith('versions') },
                            getAllFilesFromDir(process.out.report[0][1], relative: true, includeDir: false)
                        ).match("csv")
                    }
            )
        }
    }

    test("tsv") {

        when {
            process {
                """
                input[0] = [ [id: "tsv_config"],
                    file(params.modules_testdata_base_path + 'generic/config/config_network.datavzrd.yaml', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'generic/tsv/network.tsv', checkIfExists: true)
                    ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                            process.out.findAll { key, val -> key.startsWith('versions') },
                            getAllFilesFromDir(process.out.report[0][1], relative: true, includeDir: false)
                        ).match("tsv")
                    }
            )
        }
    }

    test("generic - [ yaml, [ csv, tsv ] ] - report") {

        when {
            process {
                """
                input[0] = channel.of('''
                    datasets:
                      test:
                        path: test.csv
                      network:
                        path: network.tsv
                    views:
                      test:
                        dataset: test
                        render-table:
                          columns: {}
                      network:
                        dataset: network
                        render-table:
                          columns: {}
                    '''.stripIndent())
                    .collectFile(name: 'config_multiple.datavzrd.yaml')
                    .map { config -> [ [id: "multiple_config"],
                        config,
                        [
                            file(params.modules_testdata_base_path + 'generic/csv/test.csv', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'generic/tsv/network.tsv', checkIfExists: true)
                        ]
                    ] }
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                            sanitizeOutput(process.out, unstableKeys: ['report']),
                            getAllFilesFromDir(process.out.report[0][1], relative: true, includeDir: false)
                        ).match()
                    }
            )
        }
    }

    test("csv - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [ [id: "csv_config"],
                    file(params.modules_testdata_base_path + 'generic/config/config_test.datavzrd.yaml', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'generic/csv/test.csv', checkIfExists: true)
                    ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

    test("no_config_file") {
        when {
            process {
                """
                input[0] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.out['report'].isEmpty() },
                { assert snapshot(process.out).match() }
            )
        }
    }
}
